style.css:
@-moz-document domain("youtube.com") {
/* Kirby Pink */
  .html5-video-player .ytp-play-progress,
  .html5-video-player .ytp-play-progress.ytp-swatch-background-color,
  .html5-video-player .ytp-swatch-background-color,
  .html5-video-player .ytp-swatch-background-color .ytp-play-progress {
    background: #E98AB8 !important;
    background-color: #E98AB8 !important;
    background-image: none !important;
  }

  /* Force SVG progress colors */
  .html5-video-player {
    --yt-spec-brand-button-background: #E98AB8 !important;
    --yt-spec-static-brand-red: #E98AB8 !important;
    --yt-spec-call-to-action: #E98AB8 !important;
  }

  /* Kirby Umbrella */
  .html5-video-player .ytp-scrubber-button {
    width: 52px !important;
    height: 52px !important;

    background: transparent url("https://www.image2url.com/r2/default/gifs/1785101599509-9bb98603-892b-4273-81e0-1e2c52a34efd.gif") center/contain no-repeat !important;

    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;

    margin-left: -19px !important;
    margin-top: -29px !important;

    transform: none !important;
  }

  .html5-video-player .ytp-scrubber-button::before,
  .html5-video-player .ytp-scrubber-button::after {
    display: none !important;
    content: none !important;
  }

  .html5-video-player .ytp-scrubber-container,
  .html5-video-player .ytp-progress-bar,
  .html5-video-player .ytp-progress-bar-container {
    overflow: visible !important;
  }
}
